import type {BlogPost} from './data';

export const november20BlogBatch:readonly BlogPost[]=[{"slug":"callcenteroutsourced-hand-a-misdialed-caller-to-the-right-queue-without-a-second-hold","heroImage":"/daily20/callcenteroutsourced/callcenteroutsourced-hand-a-misdialed-caller-to-the-right-queue-without-a-second-hold.webp","title":"Hand a misdialed caller to the right queue without a second hold","excerpt":"A routing routine that names the real destination, keeps the case attached, and caps the number of transfers.","minutes":8,"intro":"A caller who reaches the wrong queue usually knows it before the agent does. The request is for a different product, region, or department, and the current script has no place to put it. Treating the misdial as a normal call wastes two conversations and teaches the caller that the company cannot route. A short, written handoff routine keeps the caller from being placed on hold twice.","published":"2026-11-20","updated":"2026-11-20","stats":[{"value":"2.67 million","label":"U.S. customer service representative jobs in 2025","note":"BLS reports about 2.7 million customer service representative jobs; the figure frames the scale of the queue workload.","source":1},{"value":"$21.53","label":"median hourly wage in May 2025","note":"BLS median pay for customer service representatives in May 2025; wages vary by industry and geography.","source":1},{"value":"289,500","label":"projected annual openings, 2025 to 2035","note":"BLS projects annual openings from replacement needs, not from queue growth.","source":1}],"sections":[{"title":"Recognize a misdial before the script starts","paragraphs":["A misdial shows up as a mismatch between the request and the queue's scope. The caller may name a product the team does not support or ask for an office in another country. Listen for the nouns that do not belong to the current script, then confirm the mismatch with one question. Do not run the verification steps for an account the team cannot change. The confirmation should be a sentence the caller can correct, not an accusation.","Some calls look like misdials but are really misrouted by the IVR. The caller pressed the closest option because the menu had no exact match. Ask which option they chose and what they expected to reach. If several callers report the same mismatch, the defect belongs to the menu rather than the caller. Record the option path so the routing review has evidence."]},{"title":"Name the queue the caller actually needs","paragraphs":["Translate the caller's words into a queue name the current system recognizes. Keep a short list of queue names, the work each one handles, and the hours it is staffed. Read the list during the call rather than guessing from memory. If no queue matches, the correct destination may be a ticket rather than a transfer. Say which one you are choosing and why.","Confirm the destination with the caller before the transfer begins. A simple sentence such as 'I am sending you to the billing queue for the invoice on the second account' catches a wrong assumption. If the caller hesitates, ask what part of the description is wrong. Reconfirm before you dial, because a second transfer after a failed one is harder to recover. Write the confirmed queue in the case note."]},{"title":"Use a warm handoff with the case attached","paragraphs":["A warm handoff gives the next agent the reason for the call, the identity checks already done, and the caller's preferred callback number. Introduce the receiving agent by role, not by guessing a name. State the request in one sentence and hand over the case number. Stay on the line until the receiving agent confirms they have the record. A silent transfer with no context is how callers end up repeating the whole story.","Set a maximum hold time for the warm handoff. If the receiving queue does not answer within the stated window, return to the caller with a named alternative. Do not leave the caller listening to a queue that may never pick up. The alternative can be a scheduled callback or a ticket with an owner. Record which path was used and how long the handoff took."]},{"title":"When to return the caller to the IVR","paragraphs":["Returning a caller to the IVR is sometimes the honest option, especially when the destination is self-service. Explain which menu option to choose and what will happen next. Do not send the caller back to the main menu without that instruction. If the caller cannot navigate the menu, offer a person instead. The choice should depend on the caller's ability, not on the queue's convenience.","Use the IVR return only when the request can actually be completed there. A caller who needs an account change will fail in a payment menu and call again. Check that the destination path works before you recommend it. If the path is broken, log the defect and route to a person. The caller should not be the one who discovers the menu is wrong."]},{"title":"Write the misdial note the next agent can read","paragraphs":["The note should state the request, the destination, and the reason the current queue could not help. Include the identity checks completed and the ones the receiving team still needs. Add the caller's words for the request so the next agent can hear the nuance. Keep blame out of the note, including phrases about the caller pressing the wrong button. A factual note travels better than a judgment.","Use the same fields for every misdial so the log can be counted. The fields can be as simple as source queue, destination queue, request type, and outcome. A free-text note is useful for the story but hard to aggregate. Pair the fields with one short narrative line. That combination supports both the next call and the monthly review without extra reporting work."]},{"title":"Set the limit on transfer attempts","paragraphs":["Two transfers should be the ceiling for a routine request. A third transfer means the routing table or the queue scope is wrong, not that the caller is difficult. When the limit is reached, stop and offer a named owner who will call back. Give the caller a reference number and a time window. Escalate the failed route to the supervisor on duty.","Track how often the limit is hit and which queue pairs produce it. A repeated failure between the same two queues is a design problem with a small fix. A scattered pattern may point to an unclear queue scope. Review the pairs weekly until the count falls. Publish the limit so agents do not improvise a fourth attempt or invent a new route."]},{"title":"Measure misdials as a routing defect","paragraphs":["Count misdials as a share of total contacts and by destination queue. A rising share in one queue suggests the menu or the queue description has drifted. Compare the count with the IVR option paths callers report. The comparison separates caller error from routing design error. Use a stable definition so month-to-month changes mean something before the next review rather than after it.","Do not use the misdial count to judge individual agents. The agent who reports a misdial is doing the queue a favor. Reward the report by fixing the route, not by adding it to a quality penalty. If the count appears in a scorecard, pair it with a repair metric. The useful question is how many routes were fixed, not how many callers were blamed."]},{"title":"Review the misdial log monthly","paragraphs":["The monthly review should read a sample of notes, not just the totals. Look for the same destination appearing with different queue names. Check whether the caller was told the truth about the wait and the transfer. Confirm that failed routes produced an owner and a callback. End the review with one route to fix and one field to clarify.","Invite the client to the review when the defect sits in their menu or queue scope. Bring the option paths and three anonymized notes. Ask for a decision on the queue name or the menu label, not a general promise to improve. Record the decision and the date it takes effect. Follow up at the next review with the same sample method."]}],"controlTable":[{"data":"Misdial signal","agent":"Confirms the request is outside queue scope","manager":"Owns the scope list and the transfer cap"},{"data":"Destination","agent":"Names the receiving queue and confirms it","manager":"Approves queue names and hours"},{"data":"Handoff note","agent":"Attaches checks, request, and callback number","manager":"Reviews a sample each month"},{"data":"Failed route","agent":"Escalates after the second attempt","manager":"Fixes the route with the client"}],"scripts":[{"situation":"Confirming a destination","text":"I am sending you to the billing queue for the invoice on the second account. The team there can see the case number, so you will not have to repeat the whole story. If they cannot help, ask for a supervisor and I will follow up."},{"situation":"Stopping a third transfer","text":"I have tried two teams and neither owns this request, so I am not going to send you to a third hold. I am taking your number and opening a case with a named owner who will call you back today."}],"faqs":[{"question":"Should an agent transfer a caller who simply picked the wrong IVR option?","answer":"Yes, when the correct destination is clear and the handoff can carry the context. The agent should confirm the destination and stay on the line long enough for the receiving team to accept the case."},{"question":"What if the receiving queue is closed?","answer":"Do not transfer into a closed queue. Offer a scheduled callback or a ticket with an owner, give the caller a reference number, and record the fallback in the case."}],"sources":[{"name":"Occupational Outlook Handbook: Customer Service Representatives","organization":"Bureau of Labor Statistics","date":"2026","url":"https://www.bls.gov/ooh/office-and-administrative-support/customer-service-representatives.htm","note":"Employment, wage, training, and outlook figures for customer service representatives."},{"name":"ISO 18295-1:2017 Customer contact centres","organization":"International Organization for Standardization","date":"2017","url":"https://www.iso.org/standard/64739.html","note":"Requirements for customer contact centre processes, people, and performance."},{"name":"Fact Sheet #64: Call Centers under the Fair Labor Standards Act","organization":"U.S. Department of Labor, Wage and Hour Division","date":"2008","url":"https://www.dol.gov/agencies/whd/fact-sheets/64-flsa-call-centers","note":"Hours-worked, rest-period, and recordkeeping rules for call center employees."},{"name":"GAO-20-283G: Assessing Data Reliability","organization":"U.S. Government Accountability Office","date":"2020","url":"https://www.gao.gov/products/gao-20-283g","note":"A practical framework for documenting data sources, testing reliability, and stating limitations."}],"related":[{"label":"Audit an IVR menu after a product change","href":"/blog/callcenteroutsourced-audit-an-ivr-menu-after-a-product-change"},{"label":"Reporting and QA","href":"/services/reporting-and-qa"}]},{"slug":"callcenteroutsourced-audit-overnight-voicemail-timestamps-against-the-queue-clock","heroImage":"/daily20/callcenteroutsourced/callcenteroutsourced-audit-overnight-voicemail-timestamps-against-the-queue-clock.webp","title":"Audit overnight voicemail timestamps against the queue clock","excerpt":"A timestamp audit that compares the PBX, the ticket, and the first listen without guessing at the cause.","minutes":8,"intro":"Overnight voicemail is where small clock errors become customer complaints. A message that arrived at 11:40 p.m. can look like a 2:10 a.m. arrival if the telephony and ticket systems disagree. The audit below compares three times against one reference, records the cause, and retests the fix. It is deliberately narrow so a small team can repeat it every month.","published":"2026-11-20","updated":"2026-11-20","stats":[{"value":"2.67 million","label":"U.S. customer service representative jobs in 2025","note":"BLS reports about 2.7 million customer service representative jobs; the figure frames the scale of the queue workload.","source":1},{"value":"$21.53","label":"median hourly wage in May 2025","note":"BLS median pay for customer service representatives in May 2025; wages vary by industry and geography.","source":1},{"value":"289,500","label":"projected annual openings, 2025 to 2035","note":"BLS projects annual openings from replacement needs, not from queue growth.","source":1}],"sections":[{"title":"Pick one clock as the queue reference","paragraphs":["Every voicemail carries at least three times: the carrier or PBX stamp, the ticket creation time, and the time the agent listened. Those clocks drift, and the drift changes the story of an overnight call. Choose the queue's workforce management clock as the reference, then document why. A single reference makes the comparison repeatable. Without one, each review starts by arguing about which time is true.","Write the reference clock's source, time zone, and daylight-saving behavior in the audit note. Name the person who can change it. A reference that nobody owns will be reset by the next vendor update. Record the current offset from coordinated universal time during the audit. The offset is evidence that the comparison used the right basis for every comparison in the file."]},{"title":"Collect the three timestamps for each voicemail","paragraphs":["Pull the voicemail list for the overnight window from the telephony system, not from the inbox. The inbox shows when someone opened the message, which is a different event. For each message, capture the PBX stamp, the ticket stamp, and the first listen time. Keep the message identifier so the files can be joined later. A sample of twenty to thirty messages is enough to show a pattern.","Export the data before the retention window closes. Some systems purge voicemail audio earlier than the ticket record. Save the export with a date and the query used. Do not retype times from a screen if an export exists. If you must transcribe, have a second person check the first five rows; the audit is only as good as the join between the two systems."]},{"title":"Compare the PBX clock to the ticket clock","paragraphs":["Calculate the difference between the PBX stamp and the ticket stamp for each message. A consistent offset points to a clock setting, while a scattered difference points to processing delay. Plot the differences by hour to see whether the gap grows overnight. A gap that grows suggests a queue or integration problem rather than a single bad clock. Write the direction of the offset, not just the size.","Check the ticket system's time zone separately from its clock. A correct clock set to the wrong zone produces a clean, wrong offset. Compare both systems to the reference at the same moment. Use a known test message sent during the audit window. Label the result as clock drift, zone error, or processing delay; each cause has a different fix."]},{"title":"Reconstruct the overnight timeline","paragraphs":["Build a timeline for each sampled message from arrival to first listen. Mark the handoff between the telephony system and the ticket system. Add the shift change and any automated routing. The timeline shows whether the delay happened before or after the record existed. A long delay before the ticket is a different problem from a ticket that sat unopened.","Use the timeline in the client conversation instead of a single average. An average hides the messages that arrived just before the shift ended. Show the earliest and latest arrival, the shift boundary, and the first listen. If a message crossed a weekend, mark that explicitly. The client can act on a sequence even when they dispute the average and can see the sequence for themselves."]},{"title":"Handle daylight saving and time-zone edges","paragraphs":["Test the audit window that contains a daylight-saving change. A system that stores local time may repeat or skip an hour. Compare the stored stamp with a coordinated universal time source for that night. If the systems disagree, state which one preserved the offset. Do not silently normalize the times without recording the conversion, because a later reviewer cannot tell what changed.","Do the same check when the client and the queue sit in different time zones. The ticket may display client local time while the PBX stores site time. Put both zones in the audit table next to the reference. Ask the client which zone their staff read during the overnight shift. A zone assumption is the most common source of a false late-arrival finding."]},{"title":"Write a timestamp exception the client can read","paragraphs":["An exception note should state the observed times, the reference, and the size of the difference. Avoid words like 'late' until the cause is known. Describe the event: the message arrived at one time and the ticket appeared at another. Add the effect on the customer, such as a callback outside the promised window. End with the question the client needs to answer.","Attach the export rows that support the note, not the whole file. Redact phone numbers and names the client does not need. Keep the message identifier so the client can check the source. If the cause is still unknown, label the note as an open finding. A clear open finding is more useful than a confident wrong conclusion that the client can still challenge."]},{"title":"Fix the clock source, not just the log","paragraphs":["Correcting the displayed time in a report does not fix the source. Ask the telephony administrator to confirm the network time source and the update interval. Check whether the ticket integration passes a timestamp or lets the receiving system create one. If the integration creates its own time, the delay belongs to the integration. Document the change and the date it was applied.","Retest with a live message after the fix. Compare the new offset with the audit result and keep both records. A fix that is not retested is only a hope. If the offset remains, escalate to the vendor with the test evidence. Put the retest date in the monthly review so the repair does not disappear, and keep the old export for comparison."]},{"title":"Review the timestamp audit each month","paragraphs":["Run a smaller version of the audit every month after the first deep review. Sample ten messages across the overnight window and compare the same three times. Track the offset and the share of messages with a gap over the agreed threshold. A stable offset is easier to live with than a growing one. Report both the size and the trend.","Close the review with one owner and one date for each unresolved cause. If the client owns the telephony system, send the finding to the named contact. If the vendor owns the integration, keep the ticket number in the review. Do not reopen the same finding without new evidence. The monthly review should retire findings, not accumulate them or turn into a permanent agenda item."]}],"controlTable":[{"data":"Reference clock","agent":"Uses it for every comparison","manager":"Owns the source and the offset record"},{"data":"Voicemail export","agent":"Keeps the message identifier","manager":"Approves the sample window"},{"data":"Timestamp exception","agent":"Writes observed times and effect","manager":"Decides the client-side fix"},{"data":"Retest","agent":"Sends a live message after the fix","manager":"Confirms the repair date"}],"scripts":[{"situation":"Opening a timestamp review","text":"I compared the voicemail arrival time with the ticket time for ten overnight messages. The queue clock is the reference, and the difference is recorded in the file. I am not calling the message late until we agree which system created the ticket time."},{"situation":"Escalating a clock drift","text":"The PBX clock is running four minutes behind the queue reference, and the gap grows after the overnight reset. I have kept the export and the test message so your telephony vendor can see the pattern."}],"faqs":[{"question":"Which timestamp should be treated as the arrival time?","answer":"Use the telephony or PBX stamp as the arrival evidence and the queue clock as the reference for comparison. The ticket time records when the queue system created the case, not when the customer called."},{"question":"Does a consistent offset still need fixing?","answer":"Yes, because the offset distorts every overnight report and may grow. Document the size, fix the source, and retest; do not simply adjust the report."}],"sources":[{"name":"Occupational Outlook Handbook: Customer Service Representatives","organization":"Bureau of Labor Statistics","date":"2026","url":"https://www.bls.gov/ooh/office-and-administrative-support/customer-service-representatives.htm","note":"Employment, wage, training, and outlook figures for customer service representatives."},{"name":"ISO 18295-1:2017 Customer contact centres","organization":"International Organization for Standardization","date":"2017","url":"https://www.iso.org/standard/64739.html","note":"Requirements for customer contact centre processes, people, and performance."},{"name":"Fact Sheet #64: Call Centers under the Fair Labor Standards Act","organization":"U.S. Department of Labor, Wage and Hour Division","date":"2008","url":"https://www.dol.gov/agencies/whd/fact-sheets/64-flsa-call-centers","note":"Hours-worked, rest-period, and recordkeeping rules for call center employees."},{"name":"GAO-20-283G: Assessing Data Reliability","organization":"U.S. Government Accountability Office","date":"2020","url":"https://www.gao.gov/products/gao-20-283g","note":"A practical framework for documenting data sources, testing reliability, and stating limitations."}],"related":[{"label":"Prepare the queue for a client system outage without losing the record","href":"/blog/callcenteroutsourced-prepare-the-queue-for-a-client-system-outage-without-losing-the-record"},{"label":"Reporting and QA","href":"/services/reporting-and-qa"}]},{"slug":"callcenteroutsourced-write-a-no-show-follow-up-note-the-next-shift-can-act-on","heroImage":"/daily20/callcenteroutsourced/callcenteroutsourced-write-a-no-show-follow-up-note-the-next-shift-can-act-on.webp","title":"Write a no-show follow-up note the next shift can act on","excerpt":"A note format that separates causes, names one next action, and closes the loop when the customer returns.","minutes":8,"intro":"A no-show note is often written at the end of a long shift, which is exactly when detail is scarce. The next shift inherits a name, a time, and a note that says 'no answer.' The customer then calls again and starts over. A short, consistent note format gives the next shift a fact pattern and one action instead of a puzzle. It also gives the client a cause it can fix rather than a vague apology.","published":"2026-11-20","updated":"2026-11-20","stats":[{"value":"2.67 million","label":"U.S. customer service representative jobs in 2025","note":"BLS reports about 2.7 million customer service representative jobs; the figure frames the scale of the queue workload.","source":1},{"value":"$21.53","label":"median hourly wage in May 2025","note":"BLS median pay for customer service representatives in May 2025; wages vary by industry and geography.","source":1},{"value":"289,500","label":"projected annual openings, 2025 to 2035","note":"BLS projects annual openings from replacement needs, not from queue growth.","source":1}],"sections":[{"title":"Define what counts as a no-show","paragraphs":["A no-show is not simply an empty slot on the calendar. Define the waiting period, the contact attempts, and the channel where the appointment was booked. Decide whether a late arrival within ten minutes still counts. Write the definition where agents and the client can both read it. A shared definition prevents the same customer from being counted twice or counted against the wrong shift.","Separate a customer no-show from a client-side cancellation or a system failure. A confirmation link that never sent is not a customer choice. A clinician who left early is not a no-show either. Use distinct reason codes so the follow-up note does not blame the wrong party. Review the codes with the client before the first report and keep the list short."]},{"title":"Capture the attempt trail before the shift ends","paragraphs":["Record every reminder and contact attempt with a time and a channel. Include the confirmation response, the voicemail, and the final call before the appointment. The trail should let the next shift see what the customer already knows. If an attempt failed, record the failure rather than leaving the field blank. A blank field looks like no one tried and a blank field cannot be corrected later.","Do not reconstruct the trail from memory at the end of the shift. Update the record after each attempt while the details are fresh. If the systems are slow, use a temporary field and reconcile it before closing. The next shift should not inherit a puzzle. A complete trail also protects the agent if the customer disputes the reminder or asks for the contact history."]},{"title":"Write the note in the next shift's language","paragraphs":["The next shift needs the facts, not the story of the day. Start with the appointment time, the service, and the last contact attempt. State what the customer said in their own words, quoted briefly. Avoid abbreviations that only the day team uses. The note should make sense to someone who has never spoken to this customer without needing a second explanation.","Put the next action at the top if the note is long. Use a short heading such as 'Call at 9:00' or 'Hold for client decision.' A reader should not have to hunt for the instruction. Keep the narrative below the action for context. The format should be the same for every no-show note so the shift can scan a list."]},{"title":"Name the next action and its deadline","paragraphs":["Every note should end with one owner, one action, and one deadline. The action might be a call, a reschedule offer, or a message to the client. The deadline should be a time, not 'soon' or 'next week.' If the action depends on the client, name the client contact and the date you will chase. An action without a deadline is a wish.","Decide what happens if the deadline passes without a response. The fallback might be a second call, a letter, or a closure with a reason. Write the fallback in the same note so the next shift does not invent it. Do not let a no-show sit open indefinitely without a review date. The queue needs a way to retire stale work."]},{"title":"Separate a client no-show from a customer no-show","paragraphs":["Client no-shows happen when the client contact does not attend a scheduled review or provide a decision. Customer no-shows happen when the end customer misses the appointment. The follow-up differs because the audience differs. A client no-show may need an account manager, while a customer no-show needs a new appointment offer. Mixing them delays both and makes the count unreliable.","Use separate queues or at least separate reason codes for the two types. Report them separately to the client so the numbers are not confused. If the client's own staff caused the delay, say so factually and without heat. The note should support a conversation about the process, not a blame contest. Clear categories make that conversation possible without turning the report into a complaint."]},{"title":"Protect the record from blame language","paragraphs":["Write 'the customer did not answer three calls' instead of 'the customer ignored us.' The first sentence describes evidence, while the second assigns motive. Agents do not know why someone missed an appointment. Keep speculation out of the note even when the pattern looks familiar. A neutral record survives a complaint review and a client audit, and the wording also protects the agent.","Apply the same standard to the client's staff and to the queue. If a reminder failed, write that the reminder failed and what was checked. Do not soften a system defect into a customer issue. The client needs the accurate cause to fix it. Neutral language is not vague language; it is specific about events rather than intentions and that difference is what the client reviews."]},{"title":"Close the loop when the customer returns","paragraphs":["When the customer calls back or attends a new appointment, link the new record to the original no-show. Note what changed and whether the follow-up worked. Close the original note with the outcome rather than leaving it open. If the customer returns through a different channel, search by the identifiers on the first record. The link is what makes the no-show rate explainable.","Ask the customer one open question about the missed appointment if the context allows. The answer may reveal a reminder problem, a transport issue, or a schedule conflict. Record the answer in the customer's words, not a category alone. Use the categories for counting and the words for improvement. Do not turn the question into a survey at a sensitive moment."]},{"title":"Review no-show notes weekly","paragraphs":["Review a sample of notes each week for completeness and tone. Check that each note has an owner, an action, and a deadline. Look for reason codes that are used inconsistently across shifts. Pick one recurring cause and trace it to a process step. End the review with one change the team can test next week with a named owner and a review date.","Share the findings with the client in a short summary, not a raw dump. Include the count, the top two causes, and the change being tested. Ask the client to confirm any cause that sits on their side. Keep the summary to one page so it gets read. The weekly habit prevents a month of notes from becoming an untouchable archive."]}],"controlTable":[{"data":"No-show reason","agent":"Uses the agreed code and quotes the customer","manager":"Owns the code list"},{"data":"Attempt trail","agent":"Logs time, channel, and result","manager":"Checks completeness weekly"},{"data":"Next action","agent":"Names one owner and one deadline","manager":"Approves client-side follow-up"},{"data":"Return contact","agent":"Links the new record to the old one","manager":"Reviews closure and repeat rate"}],"scripts":[{"situation":"Handing off a no-show","text":"The customer missed the 2:30 appointment and did not answer the reminder or two calls. The next action is a reschedule call at 9:00 tomorrow, and the fallback is a letter if there is no answer. The reason is recorded as an unanswered reminder, not as a refusal."},{"situation":"Closing a returned customer","text":"The customer called back today and booked the same service for Thursday. I linked the new appointment to the original no-show and noted that the text reminder was the only attempt that reached them."}],"faqs":[{"question":"How many contact attempts belong before a no-show is logged?","answer":"Use the client's written rule, then apply it consistently. A common pattern is one reminder before the appointment and two attempts after, but the count should match the service and the customer's consent."},{"question":"Should a no-show note include the customer's reason?","answer":"Include it when the customer offers one, in their own words. Do not pressure them for a reason, and do not replace the reason code with a guess."}],"sources":[{"name":"Occupational Outlook Handbook: Customer Service Representatives","organization":"Bureau of Labor Statistics","date":"2026","url":"https://www.bls.gov/ooh/office-and-administrative-support/customer-service-representatives.htm","note":"Employment, wage, training, and outlook figures for customer service representatives."},{"name":"ISO 18295-1:2017 Customer contact centres","organization":"International Organization for Standardization","date":"2017","url":"https://www.iso.org/standard/64739.html","note":"Requirements for customer contact centre processes, people, and performance."},{"name":"Fact Sheet #64: Call Centers under the Fair Labor Standards Act","organization":"U.S. Department of Labor, Wage and Hour Division","date":"2008","url":"https://www.dol.gov/agencies/whd/fact-sheets/64-flsa-call-centers","note":"Hours-worked, rest-period, and recordkeeping rules for call center employees."},{"name":"GAO-20-283G: Assessing Data Reliability","organization":"U.S. Government Accountability Office","date":"2020","url":"https://www.gao.gov/products/gao-20-283g","note":"A practical framework for documenting data sources, testing reliability, and stating limitations."}],"related":[{"label":"Set a callback attempt cap before the promise window closes","href":"/blog/callcenteroutsourced-set-a-callback-attempt-cap-before-the-promise-window-closes"},{"label":"Services","href":"/services"}]},{"slug":"callcenteroutsourced-run-a-qa-score-dispute-with-a-two-reviewer-rule","heroImage":"/daily20/callcenteroutsourced/callcenteroutsourced-run-a-qa-score-dispute-with-a-two-reviewer-rule.webp","title":"Run a QA score dispute with a two-reviewer rule","excerpt":"A dispute process that uses a specific objection, an independent second listen, and a written outcome.","minutes":8,"intro":"A score dispute is a test of the quality process, not a fight between an agent and a supervisor. When the same person scores the call and decides the dispute, the agent learns that appealing is pointless. A two-reviewer rule adds one independent listen and a written decision. The process below keeps the review fast enough to use and specific enough to trust.","published":"2026-11-20","updated":"2026-11-20","stats":[{"value":"2.67 million","label":"U.S. customer service representative jobs in 2025","note":"BLS reports about 2.7 million customer service representative jobs; the figure frames the scale of the queue workload.","source":1},{"value":"$21.53","label":"median hourly wage in May 2025","note":"BLS median pay for customer service representatives in May 2025; wages vary by industry and geography.","source":1},{"value":"289,500","label":"projected annual openings, 2025 to 2035","note":"BLS projects annual openings from replacement needs, not from queue growth.","source":1}],"sections":[{"title":"Open the dispute window at the right moment","paragraphs":["Tell agents when a score becomes reviewable and how long the window stays open. A window that opens before the coaching conversation turns the review into an argument. A window that closes too fast punishes someone who was on leave. Publish the rule in the quality guide and the scorecard footer. The date should be visible on the score itself.","Start the window when the agent receives the score and the recording. Confirm the receipt so the clock has evidence. If the agent is absent, pause the window and record the pause. Do not let a supervisor close a dispute because the agent did not respond during vacation. The process should be firm about the deadline and fair about the reason."]},{"title":"Require the agent's specific objection","paragraphs":["A dispute needs a specific line, a reason, and the evidence the agent wants reviewed. 'I disagree with the score' is not enough to assign a reviewer. Ask the agent to name the behavior, the timestamp, and what the scorecard says. A specific objection is easier to uphold or deny. It also protects the agent from a vague complaint that cannot be answered.","Give the agent a short form with three fields: scorecard line, what happened, and what should change. Let them attach a note or point to a timestamp. Do not require legal language or a long essay. The form should take five minutes, not an hour. If the agent cannot be specific, the coach helps them frame the question before the window closes."]},{"title":"Assign a reviewer who did not score the call","paragraphs":["The reviewer should be someone other than the original scorer. A second reader reduces the chance that a scoring error survives because the first reviewer defends it. The reviewer needs the rubric, the recording, and the agent's objection. They do not need the original scorer's conclusion before they listen. Independence is the point of the rule, not seniority and the agent should see who reviewed the call.","If the site is too small for a fully independent reviewer, use a reviewer from another queue or a rotating peer. Document the exception and the reason. Do not let the original scorer review their own dispute just because no one else is available. A delayed independent review is better than a fast self-review. Set a maximum delay so the case does not stall."]},{"title":"Compare the scorecard line to the recording","paragraphs":["The reviewer listens to the segment named in the objection, then the surrounding minute. They check the rubric's definition before deciding. A score can be wrong because the behavior was misheard or because the rubric was misapplied. Separate those two causes in the decision. The fix differs: one needs a correction, the other needs calibration and the report should name which one applies.","Write down the timestamp and the exact words that support the decision. A decision without evidence is just a second opinion. If the recording is unclear, say so and decide what the standard requires. Do not fill a gap with assumption. The written evidence is what the agent and the client will read later, so keep it short and concrete."]},{"title":"Decide uphold, adjust, or void","paragraphs":["Three outcomes are enough: uphold the score, adjust the line, or void the evaluation. Uphold when the rubric and the recording support the original score. Adjust when the line was scored against the wrong definition. Void when the recording or the process is too flawed to judge. Write the outcome in plain words, not only a code so the agent can see the reasoning.","An adjustment should change only the line in dispute unless the review reveals a wider error. A wider error needs a separate note and a check of other calls from the same period. Do not quietly rewrite a whole scorecard to avoid a second review. Voiding should trigger a replacement evaluation when the call still matters. Record who approved the final outcome."]},{"title":"Write the decision in the agent's file","paragraphs":["The decision note should include the objection, the evidence, the outcome, and the reason. Keep it short enough to read in one sitting. Give the agent a chance to acknowledge it and add a comment. If they disagree with the decision, record that too. A file that only contains outcomes cannot explain a pattern later or explain why a score changed.","Do not hide the decision from the next coach. A resolved dispute is useful context for the next review. Mark the line as disputed and resolved so it is not reopened by accident. If the outcome changed the score, update the report and the client summary. The record should match what the agent was told, including the date and the reviewer's role."]},{"title":"Feed the pattern back into calibration","paragraphs":["Collect disputes by rubric line, not just by agent. A cluster on one line suggests the definition is unclear or the calibration drifted. Bring two anonymized examples to the next calibration session. Ask the group to score them before revealing the decisions. The discussion is more valuable than the vote, and the examples keep it grounded and the discussion stays on the rubric.","Update the rubric only when the group agrees on a definition that the examples support. Write the change and the effective date. Rebrief the scorers before the next sample. If the rubric changes often, the dispute count may rise before it falls. Track both the change and the trend, and review the examples again after sixty days so the improvement is visible."]},{"title":"Review dispute outcomes quarterly","paragraphs":["A quarterly review should show the number of disputes, the share upheld, and the lines most often adjusted. Compare the pattern with calibration results and client audit findings. A high uphold rate may mean the agents misunderstand the rubric, while a high adjustment rate may mean the scorers do. Neither number is a verdict on its own and together they point to a question.","Ask agents what would make the process more credible. Common answers include faster decisions and clearer examples. Test one change per quarter so the effect can be seen. Report the change to the client with the evidence. The goal is a process agents trust enough to use, not a process that discourages disputes by making them slow or by making the outcome predictable."]}],"controlTable":[{"data":"Dispute window","agent":"Files within the published window","manager":"Owns the deadline and the pause rule"},{"data":"Objection form","agent":"Names the line, time, and requested change","manager":"Checks specificity before routing"},{"data":"Second reviewer","agent":"Listens independently and writes evidence","manager":"Assigns a reviewer without a conflict"},{"data":"Outcome","agent":"Acknowledges the decision","manager":"Approves adjustment or void"}],"scripts":[{"situation":"Acknowledging a dispute","text":"I have your objection on the empathy line at 4:12. A reviewer who did not score this call will listen to that segment and the minute around it. You will get a written outcome with the evidence, not just a new number."},{"situation":"Explaining an adjustment","text":"The reviewer found that the rubric requires a hold before the transfer, and the recording shows one. The score is adjusted on that line only. The rest of the evaluation stands, and the calibration team will see the example."}],"faqs":[{"question":"Can the original scorer sit in the review?","answer":"They can provide context if the reviewer asks, but they should not decide the outcome. The independent reviewer listens first and writes the evidence before hearing the original rationale."},{"question":"What happens when the reviewer cannot decide?","answer":"Void the evaluation when the recording or process is too flawed to judge, and record why. If the call still matters, schedule a replacement evaluation rather than guessing."}],"sources":[{"name":"Occupational Outlook Handbook: Customer Service Representatives","organization":"Bureau of Labor Statistics","date":"2026","url":"https://www.bls.gov/ooh/office-and-administrative-support/customer-service-representatives.htm","note":"Employment, wage, training, and outlook figures for customer service representatives."},{"name":"ISO 18295-1:2017 Customer contact centres","organization":"International Organization for Standardization","date":"2017","url":"https://www.iso.org/standard/64739.html","note":"Requirements for customer contact centre processes, people, and performance."},{"name":"Fact Sheet #64: Call Centers under the Fair Labor Standards Act","organization":"U.S. Department of Labor, Wage and Hour Division","date":"2008","url":"https://www.dol.gov/agencies/whd/fact-sheets/64-flsa-call-centers","note":"Hours-worked, rest-period, and recordkeeping rules for call center employees."},{"name":"GAO-20-283G: Assessing Data Reliability","organization":"U.S. Government Accountability Office","date":"2020","url":"https://www.gao.gov/products/gao-20-283g","note":"A practical framework for documenting data sources, testing reliability, and stating limitations."}],"related":[{"label":"Build a first-call resolution measure that agents trust","href":"/blog/callcenteroutsourced-build-a-first-call-resolution-measure-that-agents-trust"},{"label":"Reporting and QA","href":"/services/reporting-and-qa"}]},{"slug":"callcenteroutsourced-plan-a-queue-handoff-when-the-client-holiday-calendar-differs","heroImage":"/daily20/callcenteroutsourced/callcenteroutsourced-plan-a-queue-handoff-when-the-client-holiday-calendar-differs.webp","title":"Plan a queue handoff when the client holiday calendar differs","excerpt":"A calendar reconciliation routine that fixes coverage, promises, and billing before the holiday arrives.","minutes":8,"intro":"Two calendars rarely agree. The client observes a regional holiday, the queue follows a national one, and the roster is built from a third list. The mismatch surfaces on the morning when half the team is off and the client expects service. A written comparison, a coverage decision, and a short reconciliation after the date prevent most of the damage.","published":"2026-11-20","updated":"2026-11-20","stats":[{"value":"2.67 million","label":"U.S. customer service representative jobs in 2025","note":"BLS reports about 2.7 million customer service representative jobs; the figure frames the scale of the queue workload.","source":1},{"value":"$21.53","label":"median hourly wage in May 2025","note":"BLS median pay for customer service representatives in May 2025; wages vary by industry and geography.","source":1},{"value":"289,500","label":"projected annual openings, 2025 to 2035","note":"BLS projects annual openings from replacement needs, not from queue growth.","source":1}],"sections":[{"title":"Put both calendars on one page","paragraphs":["Start with the client's holiday calendar and the queue's holiday calendar side by side. Mark every date where one side is closed and the other is open. Include regional holidays, not just national ones. A single page prevents the annual scramble of comparing two documents under pressure. Send it to the client contact for confirmation and keep the reply with the roster.","Add the observed date when a holiday falls on a weekend. A calendar that lists the statutory date but not the observed closure will mislead the roster. Note the client's policy for early closures and half days. Those hours matter more than the full-day closures for a small queue. Put the source and the version date on the page so the next roster can be checked."]},{"title":"Classify each holiday by queue impact","paragraphs":["Not every holiday affects the queue the same way. A client closure may reduce inbound calls, while a retail holiday may increase them. Classify each date as closed, reduced, normal, or surge. Use last year's volume and the client's business pattern as evidence. If the data is missing, label the assumption instead of guessing at the demand and say when the assumption will be tested.","Review the classification with the client because they know their customers. Ask which holidays generate contacts even when the office is closed. Some customers call precisely because they expect a closure message. The queue may need a small team for those days. Write the expected contact type next to the classification so the roster has a reason and the client can challenge it."]},{"title":"Decide who answers on a client holiday","paragraphs":["The client may be closed while the queue remains open for other clients. Decide whether the team answers, takes a message, or routes to an alternate client contact. Name the person who can approve an exception. Do not assume the account manager is available because their calendar looks free. Confirm coverage in writing before the date and keep the confirmation in the case file.","If the queue is shared across clients, a client holiday can change the mix of work rather than the volume. One client's calls disappear while another's continue. Reforecast the mix and the skills needed for that day. A roster built on total volume may leave the wrong skill short. Publish the holiday mix assumption with the schedule so the assumption is visible to the client."]},{"title":"Set the coverage promise in writing","paragraphs":["Write what the queue promises on each holiday: hours, channels, response time, and the fallback. A promise that exists only in a conversation will be interpreted differently by each shift. Put it in the client's service description and the team's quick guide. Use the same words in both places. The customer should hear the same promise from any agent and the client should hear the same wording.","Include the limit of the promise. If the team is taking messages only, say when a person will respond. If a channel is closed, say where the customer should go instead. Do not imply full service when only a voicemail is staffed. A narrow promise kept is better than a broad promise missed; review the wording with the client's compliance contact if needed."]},{"title":"Stage the handoff before the last business day","paragraphs":["Prepare the holiday handoff two business days before the last working day. Confirm the roster, the client contact list, and the escalation path. Test the voicemail and the auto-reply before the holiday starts. Send the client a short note with the hours and the named contact. A handoff prepared on the last afternoon will miss someone and leave a name without a backup.","Include the agents who will be off during the holiday. They need to know who owns their open cases. Assign each open case to a named person who is working. Do not leave a case with an agent who returns after the holiday unless the customer agreed to the wait. Update the case owner in the system, not only in a message."]},{"title":"Prepare the holiday script and voicemail","paragraphs":["The holiday script should state the dates, the hours, and what the customer can do now. Avoid a generic 'we are closed for the holidays' message that leaves the caller without a next step. Offer the self-service option or the date a person returns. Keep the message short enough to listen to twice. Test the pronunciation of dates and product names.","Record the voicemail in the languages the queue supports. Check the greeting on the first morning, not only the day it was recorded. A greeting that says 'we return Monday' on Tuesday damages trust. Assign one person to change and verify it. Put the change on the holiday checklist with a time and a backup name so the greeting can be corrected quickly."]},{"title":"Reconcile hours after the holiday","paragraphs":["After the holiday, compare the scheduled hours with the hours actually staffed. Check the contacts that arrived outside the promised window. Ask the client whether any customer was left without a response. Reconcile the payroll and the client invoice with the same record. A holiday is a common source of billing disputes because the calendars differ and the gap is often invisible until the invoice.","Record the exceptions in a short note: the date, the hours, the cause, and the fix. If the client changed a date late, say so without blame. If the queue missed a promise, say that too. Send the note to the client contact while the details are fresh. The note becomes the input for next year's calendar and the client's planning cycle."]},{"title":"Review the calendar mismatch each quarter","paragraphs":["Review the two calendars every quarter, not only in December. Client fiscal years and regional holidays change during the year. Check whether a new region was added to the account. Ask the client for their published calendar version. Update the one-page comparison and archive the old version; the archive shows what was known on each date and supports the next audit.","Use the review to retire assumptions that no longer hold. A holiday that produced no calls last year may produce a surge after a product launch. A closure that was quiet may become busy after a policy change. Keep the classification evidence with the date. The calendar is a forecast input, not a static list, and the roster should show that."]}],"controlTable":[{"data":"Calendar comparison","agent":"Confirms the dates and the observed day","manager":"Owns the client-facing version"},{"data":"Coverage decision","agent":"Names who answers and on which channel","manager":"Approves the exception"},{"data":"Holiday promise","agent":"Uses the agreed hours and fallback","manager":"Publishes the service wording"},{"data":"Reconciliation","agent":"Records actual hours and exceptions","manager":"Signs off billing and follow-up"}],"scripts":[{"situation":"Confirming a holiday handoff","text":"The client is closed on the regional holiday but the queue stays open for messages. We will answer the main line, take a message for the account team, and tell callers when a person will respond. The named contact for the day is the shift supervisor."},{"situation":"Correcting a voicemail","text":"The greeting still says we return Monday, and today is Tuesday. I am changing it now and checking the backup line before the next call. The corrected time will be logged on the holiday checklist."}],"faqs":[{"question":"Should the queue close whenever the client closes?","answer":"Not automatically. Decide by the work the queue handles for that client and the promise made to customers. Some queues take messages while the client is closed; others route to another client contact."},{"question":"What if the client changes a holiday date late?","answer":"Record the date the change was received and the coverage that was actually possible. Tell the client what was missed without blame, and update the comparison page for the next review."}],"sources":[{"name":"Occupational Outlook Handbook: Customer Service Representatives","organization":"Bureau of Labor Statistics","date":"2026","url":"https://www.bls.gov/ooh/office-and-administrative-support/customer-service-representatives.htm","note":"Employment, wage, training, and outlook figures for customer service representatives."},{"name":"ISO 18295-1:2017 Customer contact centres","organization":"International Organization for Standardization","date":"2017","url":"https://www.iso.org/standard/64739.html","note":"Requirements for customer contact centre processes, people, and performance."},{"name":"Fact Sheet #64: Call Centers under the Fair Labor Standards Act","organization":"U.S. Department of Labor, Wage and Hour Division","date":"2008","url":"https://www.dol.gov/agencies/whd/fact-sheets/64-flsa-call-centers","note":"Hours-worked, rest-period, and recordkeeping rules for call center employees."},{"name":"GAO-20-283G: Assessing Data Reliability","organization":"U.S. Government Accountability Office","date":"2020","url":"https://www.gao.gov/products/gao-20-283g","note":"A practical framework for documenting data sources, testing reliability, and stating limitations."}],"related":[{"label":"Standardize hold messaging across a multi-client queue","href":"/blog/callcenteroutsourced-standardize-hold-messaging-across-a-multi-client-queue"},{"label":"Contact us","href":"/contact-us"}]}] as unknown as readonly BlogPost[];
